import java.io.*;
import java.util.Arrays;
import java.util.Scanner;

public class Main{
	public static void main(String[] args) throws IOException{ 
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		while(true){
			String line = br.readLine();
			if (line.equals("-")) {break;}
			int len = line.length();
			String word = line;
			String hst = br.readLine();
			int m = Integer.parseInt(hst);
			for (int i = 0; i<m ; i++) {
				String st = br.readLine();
				int h = Integer.parseInt(st);
				char[] c = word.toCharArray();
				word = "";

				for (int j = h; j < h+len ; j++ ) {
					if(j < len){
						word += String.valueOf(c[j]);
					}else{
						word += String.valueOf(c[j-len]);
					}

				}

			}	
			System.out.println(word);
		}
	}
}

import java.util.Scanner;

public class Main {
	private static Scanner sc=new Scanner(System.in);
	public static void main (String[] args){
		while(true){
			String order=sc.next();
			if(order.equals("-")) break;
			System.out.println(shuffle(order));
		}
	}
	private static String shuffle(String order){
		int m=sc.nextInt();
		String str=order;
		for(int i=0;i<m;i++){
			int h=sc.nextInt();
			str=str.substring(h)+str.substring(0,h);
		}
		return str;
	}
}

