    void solve() throws IOException {
        int n = sc.nextInt();
        HashMap<String,Integer> map = new HashMap<>();
        for(int i=0;i<n;i++){
            String s = sc.next();
            map.put(s,map.getOrDefault(s,0)+1);
        }
        int maxi = 1;
        ArrayList<String> res = new ArrayList<>();
        for(String s:map.keySet()){
            int val = map.get(s);
            if(val<maxi) continue;
            if(val==maxi) res.add(s);
