public class Main {

	public static int N;
	public static Map<String, Integer> wordCount = new TreeMap<String, Integer>();

	public static void main(String[] args) {
		init();
		int max = 0;
		for (int v : wordCount.values()) {
			if (v > max) {
				max = v;
			}
		}
		for (String w : wordCount.keySet()) {
			if (wordCount.get(w) == max) {
				System.out.println(w);
			}
		}
	}

	public static void init() {
		Scanner sc = new Scanner(System.in);
		try {
			N = sc.nextInt();
			for (int i = 0; i < N; i++) {
				String w = sc.next();
				if (wordCount.containsKey(w)) {
					int count = wordCount.get(w);
					wordCount.put(w, ++count);
				} else {
					wordCount.put(w, 1);
				}
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
	}

}

import java.util.Scanner;
import java.util.TreeMap;
import java.util.Map;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        TreeMap<String,Integer> hm = new TreeMap<String,Integer>();
        int max = 0;
        for(int i = 0; i < a; i++){
            String str = sc.next();
            if(hm.containsKey(str)){
                hm.put(str, hm.get(str) + 1);
            }else{
                hm.put(str, 1);
            }
            if(max < hm.get(str)){
                max = hm.get(str);
            }
        }
        for(Map.Entry<String,Integer> e : hm.entrySet()){
            if(max == e.getValue()){
                System.out.println(e.getKey());
            }
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();

		String S[] = new String[N];
		sc.nextLine();

		for (int i = 0; i < N; i++) {
			S[i] = sc.nextLine();
		}

		Arrays.sort(S);

		int cnt = 1;
		Map<String, Integer> map = new HashMap<>();

		for (int i = 0; i < N - 1; i++) {
			if (S[i].equals(S[i + 1])) {
				cnt++;
			} else {
				map.put(S[i], cnt);
				cnt = 1;
			}
		}

		if (S[N - 2].equals(S[N - 1])) {
			map.put(S[N - 1], cnt);
		} else {
			map.put(S[N - 2], cnt);
			map.put(S[N - 1], 1);
		}

		int maxcnt = 0;

		ArrayList<String> str = new ArrayList<>();

		for (String key : map.keySet()) {
			if (map.get(key) > maxcnt)
				maxcnt = map.get(key);
		}

		for (String key : map.keySet()) {
			if (map.get(key) == maxcnt)
				str.add(key);
		}

		Collections.sort(str);
		for (String s : str) {
			System.out.println(s);
		}

		sc.close();

	}
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Map<String, Integer> countWord = new HashMap<>();
        Set<String> results = new TreeSet<>();
        int maxNum = 1;
        for(int i = 0; i < n; i++) {
            String str = sc.next();
            if(countWord.containsKey(str)) {
                int num = countWord.get(str) + 1;
                countWord.put(str, num);
                maxNum = Math.max(maxNum, num);
            }
            else countWord.put(str, 1);
        }
        for(String key : countWord.keySet()) {
            if(countWord.get(key) == maxNum) results.add(key);
        }

        for(String ans : results) System.out.println(ans);
    }
}

