        for (int i = 0; i < n; i++) {
            bArr[i] = sc.nextInt();
        }
        for (int i = 0; i < n - 1; i++) {
            cArr[i] = sc.nextInt();
        }

        int sum = 0;
        sum += bArr[aArr[0]];
        for (int i = 1; i < n; i++) {
            sum += bArr[aArr[i]];
            boolean hoge = aArr[i - 1] + 1 == aArr[i];
            if (hoge) {
//                System.out.println(i + " x");
                sum += cArr[aArr[i] - 1];
            }
        }

        // write your code
        System.out.println(sum);
    }

