            int n = Integer.parseInt(in.next());
            int h[] = new int[n];
            for (int i = 0; i < n; i++) {
                h[i] = Integer.parseInt(in.next());
            }
            // 最初の旅館は必ず見えるので1
            int ans = 1;

            for (int i = 1; i < n; i++) {
                int cnt = 0;
                for (int j = 0; j <= i - 1; j++) {
                    if (h[i] >= h[j]) ++cnt;
                }
                if (cnt >= i) ans++;
            }
            // 出力
            out.println(ans);

        }

    }
}

