      for (int j = i; j <= n; j++) {
        if (checkString(i, j)) {
          int k = j - i;
          if (ans < k) ans = k;
        } 
      }
    }
  }

  boolean checkString(int lo, int hi) {
    for (int i = lo; i < hi; i++) if (!checkChar(i)) return false;
    return true;
  }

  boolean checkChar(int i) {
    char[] cs = new char[] { 'A', 'C', 'G', 'T' };
    for (char c: cs) if (s.charAt(i) == c) return true;
    return false;
  }

