      if (l[i]-1 > 0) {
        if (acCount[l[i]-1] == acCount[l[i]-2]) {
          ans--;
        }
      }
      else if (!(S.charAt(0) == 'A' && S.charAt(1) == 'C')) {
        ans--;
      }

      if (r[i] < S.length() && acCount[r[i]-2] != acCount[r[i]-1]) {
        ans--;
      }
      System.out.println(ans);
    }
    //System.out.println(Arrays.toString(acCount));
  }
}

