        N = sc.nextInt();
        T = sc.nextInt();
        map = new TreeMap<>();
        for (int i = 0; i < N; i++) {
            int c = sc.nextInt();
            int t = sc.nextInt();
            map.put(c, t);
        }
    }

    void solve(PrintWriter out) {
