    }

    // ======================================================================
    static class Solver {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
        	int ans = 99999;
            int N = in.nextInt();
            int T = in.nextInt();
            int c = 0;
            int t = 0;
            for(int i=0; i < N; i++) {
                c = in.nextInt();
